const ZXMODS = {};
ZXMODS["behaviour"] = function (zx, sec) {
// C2b: Behaviour profiles (port of behaviour_ui.js). Same storage keys as classic (zexBehProfiles, zexBehActive, zexTiming + the FLAT switches), so a profile made in either popup shows in the other.
// Differences on purpose: no page reload after APPLY (the sandbox re-reads by itself); EXPORT downloads through the shell; IMPORT = file OR pasted text; the optional 'idle'/'power' permission prompt (Keep awake) cannot be asked from the sandbox -> a note tells you to tap APPLY once in the classic popup.
var PK = 'zexBehProfiles', AK = 'zexBehActive', TK = 'zexTiming';

// flat storage keys a profile controls  (key → value used when the profile says nothing = default OFF)
var FLAT = {
  zen_cdp_click: false, zen_type_mode: false, zen_type_style: 'style',
  zexEs1On: false, zexEs2On: false, zexEs2Pct: 30, zexHardRefreshOn: false,
  zenSweepAutoRetry: { on: true, max: 2 },
  zexplus_focus: false, zexplus_key: false, zexplus_touch: false, zexplus_idle: false, zexplus_net: 'off',
  zenFeedLikeOn: false, zenSearchLikeOn: false, zenGivLikeOn: false
};
var FKEYS = Object.keys(FLAT);

function tm(c, t, f, a, u) {
  var g = {}; g.comment = { mode: c }; g.tg = { mode: t }; g.follow = { mode: f }; g.tar = { mode: a }; g.unf = { mode: u };
  return { ui: 'advanced', g: g };
}
function mk(over, timing) { var v = {}; FKEYS.forEach(function (k) { v[k] = JSON.parse(JSON.stringify(FLAT[k])); }); Object.keys(over).forEach(function (k) { v[k] = over[k]; }); return { flat: v, timing: timing }; }

var BUILT = [
  { id: 'b_safe', name: 'SAFE', icon: '🛡', desc: 'Slowest and most careful. Long gaps, breaks, human typing, all safety on. Best for a new or valuable account.',
    vals: mk({ zen_cdp_click: true, zen_type_mode: true, zexEs1On: true, zexEs2On: true, zexEs2Pct: 50, zexHardRefreshOn: true, zenFeedLikeOn: true, zenSearchLikeOn: true, zenGivLikeOn: true }, tm('slow', 'slow', 'slow', 'slow', 'slow')) },
  { id: 'b_balanced', name: 'BALANCED', icon: '⚖', desc: 'Normal pace with human typing and the safety nets. A good everyday setting.',
    vals: mk({ zen_cdp_click: true, zen_type_mode: true, zexEs1On: true, zexHardRefreshOn: true, zenFeedLikeOn: true, zenSearchLikeOn: true }, tm('fast', 'fast', 'slow', 'slow', 'slow')) },
  { id: 'b_fast', name: 'FAST', icon: '🚀', desc: 'Flash Lite speed for comments (quick but human-looking), fast gaps for follow / unfollow. Safety nets stay on.',
    vals: mk({ zen_cdp_click: true, zexEs1On: true, zexHardRefreshOn: true }, tm('flashlite', 'flashlite', 'fast', 'fast', 'fast')) },
  { id: 'b_flash', name: 'FLASH', icon: '⚡', desc: 'Maximum speed, no breaks, no extras. Fastest possible but X may limit the account. Use carefully.',
    vals: mk({}, tm('flash', 'flash', 'fast', 'fast', 'fast')) },
  { id: 'b_stealth', name: 'STEALTH PHONE', icon: '🕶', desc: 'For Kiwi / phone runs in the background: slow pace, real (trusted) keystrokes and taps, hidden tabs act focused, screen stays awake. Shows the "being debugged" bar.',
    vals: mk({ zen_cdp_click: true, zen_type_mode: true, zen_type_style: 'live', zexEs1On: true, zexHardRefreshOn: true, zexplus_focus: true, zexplus_key: true, zexplus_touch: true, zexplus_idle: true, zenFeedLikeOn: true, zenSearchLikeOn: true }, tm('slow', 'slow', 'slow', 'slow', 'slow')) }
];


sec.innerHTML = '<h2>BEHAVIOUR PROFILES</h2><details id="bhBox"><summary>One tap changes Timing, typing, clicking, safety and likes</summary><div id="behHost"></div></details>';
const $ = (id) => sec.querySelector('#' + id);
let host = $('behHost'), custom = [], active = '', cur = null, editing = '', permNote = '', st = null;
const get = (k) => zx.storage.get(k);
const set = (o) => zx.storage.set(o);
const esc = (s) => String(s == null ? '' : s).replace(/[&<>"]/g, (c) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;' }[c]));
const same = (a, b) => { try { return JSON.stringify(a) === JSON.stringify(b); } catch (e) { return false; } };

async function snapshot() {
  const d = await get(FKEYS.concat([TK]));
  const flat = {};
  FKEYS.forEach((k) => { let v = d[k]; if (v === undefined) v = FLAT[k]; if (typeof FLAT[k] === 'boolean') v = v === true; flat[k] = v; });
  return { flat: flat, timing: d[TK] && typeof d[TK] === 'object' ? d[TK] : null };
}
function timingModes(t) { if (!t || !t.g) return null; return ['comment', 'tg', 'follow', 'tar', 'unf'].map((k) => (t.g[k] && t.g[k].mode) || 'fast'); }
function matches(vals, snap) {
  if (!same(vals.flat, snap.flat)) return false;
  if (!vals.timing) return true;
  const a = timingModes(vals.timing), b = timingModes(snap.timing);
  return !!b && snap.timing.ui === 'advanced' && same(a, b);
}
// which stored values differ from the profile (shown on the card so a CHANGED tag can be explained)
function diffKeys(vals, snap) {
  const d = [];
  FKEYS.forEach((k) => { if (!same(vals.flat && vals.flat[k], snap.flat[k])) d.push(k + ' = ' + JSON.stringify(snap.flat[k]) + ' (profile ' + JSON.stringify(vals.flat && vals.flat[k]) + ')'); });
  if (vals.timing) {
    const a = timingModes(vals.timing), b = timingModes(snap.timing);
    if (!b || snap.timing.ui !== 'advanced') d.push('timing page is not ADVANCED');
    else if (!same(a, b)) d.push('timing modes ' + b.join('/') + ' (profile ' + a.join('/') + ')');
  }
  return d;
}
async function apply(p) {
  const o = {};
  FKEYS.forEach((k) => { const v = p.vals.flat && p.vals.flat[k]; o[k] = v === undefined ? FLAT[k] : v; });
  o[AK] = p.id;
  await set(o);
  if (p.vals.timing) {
    if (window.__ZXT && window.__ZXT.applyProfile) await window.__ZXT.applyProfile(p.vals.timing);
    else { say('⚠ Timing module not loaded — timing part NOT applied (other settings were).', 'err'); await refresh(); return; }
  }
  permNote = o.zexplus_idle ? 'Keep awake needs an extra permission that cannot be asked from this panel: open the CLASSIC popup → Behaviour → APPLY once.' : '';
  say('✓ ' + p.name + ' applied', 'ok');
  await refresh();
}
async function load() {
  const d = await get([PK, AK]);
  custom = Array.isArray(d[PK]) ? d[PK].filter((p) => p && p.id && p.vals) : [];
  active = d[AK] || '';
  cur = await snapshot();
}
const saveCustom = () => set({ zexBehProfiles: custom });
const uid = () => 'c_' + Date.now().toString(36) + Math.random().toString(36).slice(2, 5);
const all = () => BUILT.concat(custom);

function say(t, cls) {
  const el = $('behMsg'); if (!el) return;
  el.textContent = t; el.className = 'bmsg ' + (cls || '');
  clearTimeout(st); if (t && cls !== 'ok') st = setTimeout(() => { el.textContent = ''; }, 4000);
}
function chips(v) {
  const f = v.flat || {}, c = [], m = timingModes(v.timing);
  if (m) c.push('Timing: ' + (m[0] === 'flashlite' ? 'FLASH LITE' : m[0].toUpperCase()) + (new Set(m.slice(2)).size === 1 && m[2] !== m[0] ? ' · gaps ' + m[2].toUpperCase() : ''));
  if (f.zen_type_mode) c.push('Human typing' + (f.zen_type_style === 'live' ? ' (live)' : ''));
  if (f.zen_cdp_click) c.push('Stealth click');
  if (f.zexEs1On) c.push('Safety 1');
  if (f.zexEs2On) c.push('Safety 2 · ' + f.zexEs2Pct + '%');
  if (f.zexHardRefreshOn) c.push('Hard refresh');
  if (f.zexplus_focus) c.push('Focus lock');
  if (f.zexplus_key) c.push('Trusted typing');
  if (f.zexplus_touch) c.push('Touch tap');
  if (f.zexplus_idle) c.push('Keep awake');
  if (f.zexplus_net && f.zexplus_net !== 'off') c.push('Net ' + f.zexplus_net);
  if (f.zenFeedLikeOn || f.zenSearchLikeOn || f.zenGivLikeOn) c.push('Likes');
  return c;
}
function card(p, builtin) {
  const on = p.id === active, drift = on && cur && !matches(p.vals, cur);
  let h = '<div class="beh-card' + (on ? ' on' : '') + '" data-id="' + esc(p.id) + '"><div class="beh-top"><span class="beh-ic">' + (p.icon || '🎛') + '</span>';
  if (editing === p.id) h += '<input class="beh-in" id="behRen" maxlength="30" value="' + esc(p.name) + '" style="margin:0;flex:1">';
  else h += '<span class="beh-name">' + esc(p.name) + '</span>';
  if (on) h += '<span class="beh-tag">ACTIVE</span>' + (drift ? '<span class="beh-tag mod">CHANGED</span>' : '');
  h += '</div>';
  if (p.desc) h += '<div class="beh-desc">' + esc(p.desc) + '</div>';
  if (drift) h += '<div class="hint warn">differs now: ' + esc(diffKeys(p.vals, cur).join(' · ') || '?') + '</div>';
  h += '<div class="beh-chips">' + chips(p.vals).map((c) => '<span class="beh-chip">' + esc(c) + '</span>').join('') + '</div>';
